/* UI and orchestration for local training analysis. */
let selectedActivity=null,importBusy=false;
function currentMondayKey(){const prior=offset;offset=0;const k=iso(monday());offset=prior;return k}
function todayKey(){return iso(new Date())}
function activitiesSorted(){return state.activities.slice().sort((a,b)=>new Date(b.date)-new Date(a.date))}
function allWorkouts(from,until){const prior=offset,out=[];const base=monday();base.setDate(base.getDate()-prior*7);for(let t=new Date(from);t<=until;t.setDate(t.getDate()+7)){offset=Math.round((t-base)/604800000);out.push(...schedule().out)}offset=prior;return out.filter((w,i,a)=>a.findIndex(x=>x.id===w.id)===i)}
function nextWork(){const prior=offset;offset=0;let out=[];for(let i=0;i<4;i++){offset=i;out.push(...schedule().out)}offset=prior;return out.find(w=>w.id>=todayKey()&&!w.done)}
function logLabel(l){if(!l)return '';return `${l.source==='garmin'?'✓ Garmin-Training zugeordnet':'✓ Erledigt'}${l.actualSeconds?` · ${Math.round(l.actualSeconds/60)} Min tatsächlich`:''}${l.rpe?` · Anstrengung ${esc(l.rpe)}/10`:''}`}
function fitSnapshot(){const now=Date.now(),recent=state.activities.filter(a=>{const age=(now-new Date(a.date))/86400000;return age>=-1&&age<=42}),runs=recent.filter(a=>FitCoach.kind(a)==='run'),solo=runs.filter(a=>!a.context?.easyCompanion),latest=solo.slice().sort((a,b)=>new Date(b.date)-new Date(a.date))[0],longest=runs.reduce((m,a)=>Math.max(m,a.km||0),0);return {recent,runs,latest,longest}}
function currentWeek(){const prior=offset;offset=0;const s=schedule();offset=prior;return s}
function progressSummary(){const s=currentWeek();return {done:s.out.filter(x=>x.done).length,total:s.out.length}}
function metric(label,value,sub){return `<div class="stat"><label>${esc(label)}</label><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`}
function renderHome(){const p=state.profile,s=currentWeek(),n=nextWork(),f=fitSnapshot(),latest=activitiesSorted()[0],pr=progressSummary(),pct=pr.total?Math.round(pr.done/pr.total*100):0;$('#app').innerHTML=`<div class="eyebrow" style="margin-top:28px">DEIN TRAINING. DEIN FORTSCHRITT.</div><div class="section-head"><h1>Weiter geht’s,<br><span class="accent">${esc(p.name)}.</span></h1><button class="btn secondary" data-go="history">Training importieren ↗</button></div><section class="next-card"><div class="eyebrow">${n?.id===todayKey()?'HEUTE FÜR DICH':'DEINE NÄCHSTE AUFGABE'}</div><h2>${esc(n?.title||'Alles erledigt. Stark gemacht!')}</h2><p>${n?`${esc(fmt(n.date))} · ${esc(n.time)}<br>${esc(n.text)}`:'Für die nächsten Wochen sind aktuell keine offenen Aufgaben eingetragen.'}</p>${n?`<div class="row"><button class="btn" data-log="${n.id}">Training protokollieren ✓</button><button class="btn secondary" data-go="plan">Wochenplan ansehen</button></div>`:'<button class="btn secondary" data-go="settings">Nächstes Ziel definieren</button>'}</section><div class="section-head"><h2>Dein aktuelles Fitnessbild</h2><span class="note">Letzte 6 Wochen · gemessene Werte</span></div><div class="stats">${metric('Längster dokumentierter Lauf',f.longest?`${FitCoach.round(f.longest,2)} km`:'Noch offen',f.longest?'Ausdauer dokumentiert – keine Zielprognose':'Noch kein Lauf im Zeitraum dokumentiert')}${metric('Letzter Sololauf',f.latest?`${FitCoach.clock(FitCoach.pace(f.latest))} /km`:'Noch offen',f.latest?`${FitCoach.round(f.latest.km,2)} km · Ø ${f.latest.hr||'—'} bpm`:'Garmin-Datei importieren')}${metric('Diese Woche',`${pr.done} / ${pr.total}`,`${pct}% deines Wochenplans erledigt`)}</div><div class="grid"><section class="card"><div class="eyebrow">DEIN LETZTES TRAINING</div>${latest?`<h2>✓ ${esc(latest.title)} verbucht</h2><p>${esc(FitCoach.localDay(latest.date))} · ${Math.round(latest.seconds/60)} Min${latest.km?` · ${FitCoach.round(latest.km,2)} km`:''}</p><p>${esc(FitCoach.feedback(latest,state.activities,p)[0])}</p><button class="btn" data-analysis="${esc(latest.id)}">Analyse & Feedback öffnen →</button>`:'<h2>Deine erste Analyse wartet.</h2><p>Importiere die Original-FIT oder das Garmin-ZIP. Danach siehst du hier dein Feedback und die passende Aufgabe wird zugeordnet.</p><button class="btn" data-go="history">Garmin-Training importieren</button>'}</section><section class="card"><div class="eyebrow">DEIN VORBEREITUNGSSTAND</div><h2>${f.longest>=8?'✓ 8 km Laufdistanz belegt':'Laufbasis weiter aufbauen'}</h2><div class="progress"><i style="width:${pct}%"></i></div><p>Wochenplan: ${pr.done} von ${pr.total} Einheiten erledigt.</p><p class="note">Ein verlässlicher HYROX-Fitnessprozentsatz lässt sich aus Puls und Laufzeit allein nicht bestimmen. Stationskraft, Technik und die Kombination unter Belastung fehlen im Uhrsignal. Deshalb zeigen wir echte Werte und Planerfüllung statt einer scheinbar exakten Wettkampfprognose.</p><p class="note">Ziel: ${esc(p.goal)} · ${fmt(date(p.race))} <button class="text-btn" data-go="settings">ändern</button></p></section></div><section class="card" style="margin-top:20px"><div class="row spaced"><div><div class="eyebrow">KURZ & MACHBAR</div><h3>Deine Zusatzaufgabe</h3><p>${p.extra?'2 × 5 Burpees + 2 × 10 Kniebeugen. Einmal diese Woche, nur mit frischen Beinen.':'Zusatzaufgaben sind im Profil deaktiviert.'}</p></div>${p.extra?`<button class="btn secondary" id="extra">${state.extras[currentMondayKey()]?'✓ Erledigt':'Abhaken ✓'}</button>`:''}</div></section>`;bindExperience()}
function renderHistory(){const list=activitiesSorted();$('#app').innerHTML=`<div class="eyebrow" style="margin-top:28px">JEDE EINHEIT ZÄHLT</div><h1>Trainieren.<br><span class="accent">Verstehen. Weiterkommen.</span></h1><section class="card"><div class="section-head"><div><h2>Garmin-Training auswerten</h2><p>FIT / ZIP für Details · CSV für eine Übersicht</p></div><label class="btn">Dateien wählen<input id="import" type="file" accept=".fit,.zip,.csv" multiple hidden></label></div><p class="note">Lokal verarbeitet: Verläufe, Runden, Training Effect und vorhandene Laufmetriken. Deine Originaldatei bleibt im lokalen Browserarchiv. Keine Übertragung an Garmin oder einen KI-Dienst.</p><p class="note">Schon vor Version 0.4 importiert? Die alte App hat die Detailwerte nicht gespeichert. Lade dieselbe FIT/ZIP einmal erneut hoch; die Aktivität wird ergänzt und nicht doppelt gezählt.</p><p id="importStatus" role="status"></p></section><div class="activity-list">${list.map(a=>`<article class="card activity-card"><div class="row spaced"><div><div class="eyebrow">${esc(FitCoach.localDay(a.date))} · ${a.analysisVersion?'DETAILS AUSGEWERTET':'SUMMENWERTE'}</div><h2>✓ ${esc(a.title)}</h2></div><span class="pill">${a.matchedDate?'Aufgabe zugeordnet':'Training verbucht'}</span></div><div class="row"><span>${Math.round(a.seconds/60)} Min</span>${a.km?`<span>${FitCoach.round(a.km,2)} km</span><span>${FitCoach.clock(FitCoach.pace(a))} /km</span>`:''}<span>Ø ${a.hr||'—'} bpm</span></div><p>${esc(FitCoach.feedback(a,state.activities,state.profile)[0])}</p><div class="row"><button class="btn" data-analysis="${esc(a.id)}">Analyse & Feedback →</button><button class="btn secondary" data-remove="${esc(a.id)}">Entfernen</button></div></article>`).join('')||'<div class="card empty">Importiere dein Training. Hier erscheinen danach dein Feedback, Verläufe und die Zuordnung zum Plan.</div>'}</div>`;bindExperience()}
function chart(a,key,title,unit,color){const all=a.samples||[],points=all.filter(s=>FitCoach.num(s[key]));if(points.length<2)return `<p class="note">${esc(title)}: keine ausreichenden Messpunkte vorhanden.</p>`;if(key==='s'){return chart({...a,samples:all.map(s=>({...s,kmh:FitCoach.num(s.s)?s.s*3.6:null}))},'kmh','Tempoverlauf','km/h',color)}let values=points.map(s=>s[key]),lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo-=1;hi+=1}const end=Math.max(...all.map(s=>s.t)),x=t=>44+t/Math.max(1,end)*540,y=n=>160-(n-lo)/(hi-lo)*125;let path='',prev=null;for(const s of all){if(!FitCoach.num(s[key])){prev=null;continue}path+=`${prev&&s.t-prev.t<=60?'L':'M'}${x(s.t).toFixed(1)},${y(s[key]).toFixed(1)} `;prev=s}return `<figure class="chart"><figcaption>${title} <span class="note">${unit}</span></figcaption><svg viewBox="0 0 620 200" role="img" aria-label="${esc(title)} über ${Math.round(end/60)} Minuten, von ${FitCoach.round(lo)} bis ${FitCoach.round(hi)} ${unit}"><path d="M44 35V160H584" fill="none" stroke="#526048"/><path d="${path}" fill="none" stroke="${color}" stroke-width="2.4"/><text x="1" y="40">${FitCoach.round(hi)}</text><text x="1" y="160">${FitCoach.round(lo)}</text><text x="44" y="185">0 Min</text><text x="540" y="185">${Math.round(end/60)} Min</text></svg></figure>`}
function analysisContent(a){const m=a.metrics||{},lines=FitCoach.feedback(a,state.activities,state.profile),setup=a.stationSetup;const stations=FitCoach.stations(a,setup);let prior=offset;offset=0;const mon=monday();mon.setDate(mon.getDate()-35);const until=new Date(mon);until.setDate(until.getDate()+77);const options=allWorkouts(mon,until);offset=prior;return `<div class="row spaced"><div class="eyebrow">DEINE TRAININGSANALYSE</div><button class="btn secondary" id="closeAnalysis">Schliessen ×</button></div><h2>${esc(a.title)} · ${esc(FitCoach.localDay(a.date))}</h2><div class="stats">${metric('Distanz',a.km?`${FitCoach.round(a.km,2)} km`:'—','aufgezeichnet')}${metric('Aktive Timerzeit',FitCoach.clock(a.seconds),`Gesamtzeit ${FitCoach.clock(a.elapsed||a.seconds)}`)}${metric('Ø / Spitzenpuls',`${a.hr||'—'} / ${a.maxHr||'—'}`,'bpm · keine persönlichen Pulszonen')}</div><section class="feedback"><h3>Dein Feedback</h3>${lines.map(t=>`<p>${esc(t)}</p>`).join('')}</section>${a.matchedDate?`<p class="match-note">✓ Aufgabe vom ${esc(a.matchedDate)} zugeordnet. ${state.logs[a.matchedDate]?.status==='partial'?'Der Zeitumfang ist kürzer als geplant; die Aufgabe bleibt als teilweise erledigt offen.':'Die Einheit ist im Plan verbucht. Das bestätigt die Aufzeichnung, nicht automatisch jede einzelne Übung.'}</p>`:''}${chart(a,'h','Pulsverlauf','bpm','#c5fb65')}${FitCoach.kind(a)==='run'?chart(a,'s','Geschwindigkeitsverlauf','m/s · 3 m/s = 5:33 min/km','#7dcde5'):''}<div class="stats">${metric('Kadenz',m.cadence?`${m.cadence} /min`:'—','in Laufabschnitten')}${metric('Leistung',m.power?`${m.power} W`:'—','aufgezeichnet, keine Sollvorgabe')}${metric('Aerober Training Effect',a.aerobicTE!=null?String(a.aerobicTE):'—','Garmin-Wert, Skala 0 bis 5')}</div>${a.laps?.length?`<details><summary>Runden / Zwischenzeiten (${a.laps.length})</summary><div class="table-wrap"><table><thead><tr><th>Runde</th><th>Distanz</th><th>Timerzeit</th><th>Tempo /km</th><th>Ø Puls</th></tr></thead><tbody>${a.laps.map((l,i)=>`<tr><td>${i+1}</td><td>${FitCoach.round(l.km,2)} km</td><td>${FitCoach.clock(l.seconds)}</td><td>${l.km?FitCoach.clock(l.seconds/l.km):'—'}</td><td>${l.hr||'—'}</td></tr>`).join('')}</tbody></table></div></details>`:''}<form id="contextForm"><h3>Kontext für eine faire Bewertung</h3><label class="row"><input name="easyCompanion" type="checkbox" ${a.context?.easyCompanion?'checked':''}> Bewusst locker / Tempo an Begleitung angepasst</label><label>Wetter oder Besonderheiten<input name="weather" maxlength="300" value="${esc(a.context?.weather||'')}" placeholder="z. B. warm, windig, schwere Beine"></label><button class="btn secondary">Kontext speichern</button></form><form id="matchForm"><h3>Aufgabe zuordnen</h3><label>Passende Aufgabe<select name="match"><option value="">Nur als Aktivität behalten</option>${options.filter(w=>w.id>=state.profile.start&&w.id<=todayKey()).filter(w=>(FitCoach.kind(a)==='run'&&w.kind==='LAUFTRAINING')||(FitCoach.kind(a)==='gym'&&w.kind==='FIXES TRAINING')).map(w=>`<option value="${w.id}" ${a.matchedDate===w.id?'selected':''}>${w.id} · ${esc(w.title)}</option>`).join('')}</select></label><label class="row"><input type="checkbox" name="full"> Ich bestätige die vollständige Aufgabe trotz kürzerer Zeit</label><button class="btn secondary">Zuordnung speichern</button></form>${FitCoach.kind(a)==='gym'&&a.samples?.length?`<details ${setup?'open':''}><summary>Bekannten Stationsablauf zeitlich auswerten</summary><p class="note">Nur für den bekannten 5-Stationen-Zirkel: Rudern → Sled Pull → SkiErg → Snatches/Burpees → Squats/Wall Balls. Der Ablauf wird aus deinen Angaben rekonstruiert, nicht von der Uhr erkannt.</p><form id="stationForm"><div class="fields"><label>Warm-up (Minuten)<input name="warm" type="number" min="0" max="60" value="${setup?.warm??12}" required></label><label>Arbeit (Sekunden)<input name="work" type="number" min="10" max="600" value="${setup?.work??120}" required></label><label>Pause (Sekunden)<input name="rest" type="number" min="0" max="300" value="${setup?.rest??40}" required></label><label>Intervalle<input name="rounds" type="number" min="1" max="50" value="${setup?.rounds??15}" required></label><label>Erste Station (1–5)<input name="first" type="number" min="1" max="5" value="${setup?.first??4}" required></label></div><button class="btn secondary">Abschnitte berechnen</button></form>${stations.length?`<p class="note">Ungefähre Zeitfenster ab Start der Aufzeichnung. Zusätzliche Wechselpausen verschieben die Zuordnung. Ein höherer Puls allein bedeutet keine schlechtere Station.</p><div class="table-wrap"><table><thead><tr><th>Nr.</th><th>Station</th><th>Zeitfenster</th><th>Ø Puls</th></tr></thead><tbody>${stations.map(s=>`<tr><td>${s.round}</td><td>${s.station}</td><td>${FitCoach.clock(s.start)}–${FitCoach.clock(s.end)}</td><td>${s.hr||'—'}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`:''}<p class="note">${a.records||0} Originalmesspunkte · Diagramme verdichtet, Kennzahlen vor Verdichtung berechnet. ${a.context?.weather?'Dein Kontext: '+esc(a.context.weather):''}</p><p class="note">Automatisch berechnetes, regelbasiertes Feedback. Keine VO₂max-Schätzung, persönliche Pulszonen oder sichere Wettkampfprognose aus diesen Werten. <a href="https://hyrox.com/best-hyrox-preparation/" target="_blank" rel="noopener">HYROX: Ausdauer und Stationsvorbereitung</a></p>`}
function showAnalysis(id){const a=state.activities.find(a=>a.id===id);if(!a)return;selectedActivity=id;let dlg=$('#analysis');if(!dlg){dlg=document.createElement('dialog');dlg.id='analysis';dlg.className='analysis-dialog';document.body.append(dlg)}dlg.innerHTML=analysisContent(a);$('#closeAnalysis').onclick=()=>dlg.close();$('#contextForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);a.context={easyCompanion:f.has('easyCompanion'),weather:f.get('weather')};save();showAnalysis(id);render();toast('Kontext für die Auswertung gespeichert')};$('#matchForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);linkActivity(a,f.get('match'),f.has('full'));save();dlg.close();render();if(a.matchedDate)celebrate('Aufgabe zugeordnet. Deine Arbeit zählt!');else toast('Zuordnung aufgehoben')};if($('#stationForm'))$('#stationForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);a.stationSetup=Object.fromEntries([...f].map(([k,v])=>[k,+v]));save();showAnalysis(id)};if(!dlg.open)dlg.showModal()}
function bindExperience(){bind();document.querySelectorAll('[data-analysis]').forEach(b=>b.onclick=()=>showAnalysis(b.dataset.analysis));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const a=state.activities.find(x=>x.id===b.dataset.remove);if(confirm('Aktivität und ihre automatische Aufgabenverknüpfung entfernen?')){linkActivity(a,'');state.activities=state.activities.filter(x=>x.id!==a.id);save();render()}});if($('#extra'))$('#extra').onclick=()=>{const k=currentMondayKey();state.extras[k]=!state.extras[k];save();render();if(state.extras[k])celebrate('Zusatzaufgabe geschafft. Stark!')};}
function celebrate(message){let box=$('#celebration');if(box)box.remove();box=document.createElement('div');box.id='celebration';box.className='celebration';box.setAttribute('role','status');box.innerHTML=`<span class="trophy">✓</span><h2>${esc(message)}</h2><p>Eine Einheit weiter. Das ist dein Fortschritt.</p><button class="btn secondary">Weiter →</button>`;document.body.append(box);box.querySelector('button').onclick=()=>box.remove();setTimeout(()=>box.remove(),8000);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<24;i++){const p=document.createElement('i');p.className='confetti';p.style.cssText=`left:${10+Math.random()*80}%;background:${i%2?'#c5fb65':'#7dcde5'};animation-delay:${Math.random()*.4}s;transform:rotate(${Math.random()*180}deg)`;document.body.append(p);setTimeout(()=>p.remove(),2500)}}}
function workoutAt(id){const old=offset;const mon=monday();mon.setDate(mon.getDate()-old*7);const wanted=date(id);wanted.setDate(wanted.getDate()-((wanted.getDay()+6)%7));offset=Math.round((wanted-mon)/604800000);const w=schedule().out.find(x=>x.id===id);offset=old;return w}
function linkActivity(a,id,force=false){if(!a)return;const prior=a.matchedDate;if(prior&&prior!==id){delete a.matchedDate;delete a.fullConfirmed;rebuildLog(prior)}if(!id){delete a.matchedDate;delete a.fullConfirmed;return}const w=workoutAt(id);if(!w)throw Error('Aufgabe nicht gefunden');a.matchedDate=id;if(force)a.fullConfirmed=true;rebuildLog(id,w)}
function rebuildLog(id,w=workoutAt(id)){const linked=state.activities.filter(a=>a.matchedDate===id),old=state.logs[id]||{};if(!linked.length){if(old.source?.includes('garmin')&&!old.manualEdited)delete state.logs[id];else if(old.source?.includes('garmin')){state.logs[id]={...old,source:'manual',activityIds:[],actualSeconds:null}}return}const seconds=linked.reduce((s,a)=>s+a.seconds,0),comp=FitCoach.completion({seconds},w||{}),full=linked.some(a=>a.fullConfirmed)||(old.manualEdited&&old.status==='complete');state.logs[id]={...old,source:old.manualEdited?'manual+garmin':'garmin',activityIds:linked.map(a=>a.id),actualSeconds:seconds,status:full?'complete':comp.status,completed:old.completed||linked[0].date,planned:old.planned||{title:w?.title,text:w?.text,time:w?.time,kind:w?.kind,minutes:w?.minutes},rpe:old.rpe||null,recovery:old.recovery||null,notes:old.notes||''}}
function autoMatch(a){if(a.matchedDate)return;const day=FitCoach.localDay(a.date);if(day<state.profile.start||day>todayKey()||a.seconds<600)return;const w=workoutAt(day),c=w?FitCoach.candidate(a,[w]):[];if(c.length===1)linkActivity(a,c[0].id)}
function archiveFile(file){return new Promise((resolve,reject)=>{if(!window.indexedDB){resolve(false);return}const timeout=setTimeout(()=>resolve(false),4000);const req=indexedDB.open('pace-local-archive',1);req.onblocked=()=>{clearTimeout(timeout);resolve(false)};req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(Error('Originaldatei konnte nicht lokal archiviert werden'));req.onsuccess=()=>{const db=req.result,tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,`${file.name}-${file.size}-${file.lastModified}`);tx.oncomplete=()=>{clearTimeout(timeout);db.close();resolve(true)};tx.onerror=()=>{db.close();reject(Error('Lokales Dateiarchiv ist voll oder gesperrt'))}}})}
async function processImports(e){if(importBusy)return;importBusy=true;const input=e.target,files=Array.from(input.files||[]),status=$('#importStatus');if(status)status.textContent='Dateien werden gelesen, Messwerte ausgewertet und Aufgaben gesucht …';input.disabled=true;const before=JSON.stringify(state);let added=0,enriched=0,skipped=0,matched=0,errors=[],archiveWarnings=[];try{for(const file of files){try{if(file.size>30*1024*1024)throw Error('Maximal 30 MB pro Datei');let items=file.name.toLowerCase().endsWith('.csv')?parseCSV(await file.text()):file.name.toLowerCase().endsWith('.zip')?await unzipFits(await file.arrayBuffer()):parseFit(await file.arrayBuffer());for(const item of items){if(!Number.isFinite(item.seconds)||item.seconds<=0||!FitCoach.localDay(item.date))throw Error('Ungültige Aktivitätsdaten');const at=state.activities.findIndex(x=>x.id===item.id||(FitCoach.localDay(x.date)===FitCoach.localDay(item.date)&&Math.abs(x.seconds-item.seconds)<5&&Math.abs(x.km-item.km)<.1));let a;if(at<0){a=item;state.activities.push(a);added++}else{const old=state.activities[at];if(item.analysisVersion&&!old.analysisVersion){a={...old,...item,context:old.context,stationSetup:old.stationSetup,matchedDate:old.matchedDate};state.activities[at]=a;enriched++}else{a=old;skipped++}}const prior=a.matchedDate;autoMatch(a);if(a.matchedDate&&!prior)matched++;if(a.matchedDate)rebuildLog(a.matchedDate)}try{const archived=await archiveFile(file);if(!archived)archiveWarnings.push('Originalarchiv derzeit nicht verfügbar')}catch(err){archiveWarnings.push(err.message)}}catch(err){errors.push(`${file.name}: ${err.message}`)}}save();render();const s=$('#importStatus');if(s)s.textContent=`${added} neu · ${enriched} mit Details ergänzt · ${skipped} bereits vorhanden · ${matched} Aufgaben zugeordnet.${errors.length?' Fehler: '+errors.join(' · '):''}${archiveWarnings.length?' Hinweis: '+archiveWarnings.join(' · ')+'. Bitte Originaldownload behalten.':''}`;if(added||enriched)celebrate(matched?'Training ausgewertet. Aufgabe verbucht!':'Training ausgewertet. Stark gemacht!');else if(skipped)toast('Schon vorhanden – nichts doppelt gezählt.')}catch(err){state=JSON.parse(before);render();const s=$('#importStatus');if(s)s.textContent='Nicht gespeichert: '+err.message+' Bitte zuerst eine Sicherung herunterladen.'}finally{importBusy=false;input.disabled=false}}
function reprocessLegacy(){if(!state.profile||state.analysisMigration===1)return;for(const a of state.activities)autoMatch(a);state.analysisMigration=1;save()}
